# A33: the SL2(Z)-module generated by the law components (K2 u K3 u K4 = 105 profiles), fitted M_S, M_T (Cat B),
# and Hom into rho35_{s5,s7} (x) chi^k sectors (C = (rho35)_{--} (x) chi^3 is one of them).
import numpy as np, json
from law import *
xs2=sorted({Fr(h,m) for m in range(1,16) for h in range(1,3*m+1) if gcd(h,m)==1})
def allv(x): return np.concatenate([vec(c,x) for c in ('K2','K3','K4')])
F=np.array([allv(x) for x in xs2]).T; FS=np.array([float(x)*allv(-1/x) for x in xs2]).T; FT=np.array([allv(x+1) for x in xs2]).T
U,s,Vh=np.linalg.svd(F,full_matrices=False); r=int((s>1e-9*s[0]).sum()); print('rank of 105 profiles over',len(xs2),'rationals:',r,'sv',s[r-1],s[r] if r<len(s) else None)
B=U[:,:r]; C0=B.conj().T@F; CS=B.conj().T@FS; CT=B.conj().T@FT
MS=CS@np.linalg.pinv(C0); MT=CT@np.linalg.pinv(C0)
print('fit residuals S,T:',np.abs(MS@C0-CS).max(),np.abs(MT@C0-CT).max())
print('out-of-span S,T:',np.abs(FS-B@CS).max(),np.abs(FT-B@CT).max())
I=np.eye(r); print('S^4=1:',np.abs(np.linalg.matrix_power(MS,4)-I).max(),' (ST)^3=S^2:',np.abs(np.linalg.matrix_power(MS@MT,3)-MS@MS).max(),' (TS)^3=S^2:',np.abs(np.linalg.matrix_power(MT@MS,3)-MS@MS).max())
def refl(p):
    P=np.zeros((35,35)); o=35//p
    for i,rr in enumerate(R):
        y=tuple([(-x*(o*pow(o,-1,p)) + x*(p*pow(p,-1,o)))%35 for x in rr]); P[R.index(y),i]=1
    return P
Z5,Z7=refl(5),refl(7)
def sector(s5,s7,k,dual=False):
    S,T=rho(k,dual); Pr=(np.eye(35)+s5*Z5)@(np.eye(35)+s7*Z7)/4
    u,sv,_=np.linalg.svd(Pr); d=int((sv>.5).sum()); E=u[:,:d]
    return E.conj().T@S@E, E.conj().T@T@E, d
def homdim(MS1,MT1,MS2,MT2):
    d1,d2=len(MS1),len(MS2); I1,I2=np.eye(d1),np.eye(d2)
    K=np.vstack([np.kron(I2,MS1.T)-np.kron(MS2,I1), np.kron(I2,MT1.T)-np.kron(MT2,I1)])
    sv=np.linalg.svd(K,compute_uv=False); return int((sv<1e-7).sum())
if __name__=='__main__':
    res={'rank':r}
    for conv,(a1,a2) in {'M':(MS,MT),'M^T':(MS.T,MT.T)}.items():
        tab={}
        for dual in (False,True):
            for k in range(12):
                for s5 in (1,-1):
                    for s7 in (1,-1):
                        S2,T2,d=sector(s5,s7,k,dual); h=homdim(a1,a2,S2,T2)
                        if h: tab[f"{'dual' if dual else 'rho'} k={k} Z5={s5:+d} Z7={s7:+d} (dim {d})"]=h
        res[conv]=tab; print(conv,tab,flush=True)
    json.dump(res,open('module.json','w'),indent=1); np.savez('module.npz',MS=MS,MT=MT,B=B)
